query:
SELECT 'projectTags' as tbl, COUNT(*) as cnt FROM projectTags
UNION ALL SELECT 'newsTags', COUNT(*) FROM newsTags
UNION ALL SELECT 'articleTags', COUNT(*) FROM articleTags;

SELECT 'projects_without_tags' as metric, COUNT(*) as cnt FROM projects p LEFT JOIN projectTags pt ON p.id = pt.projectId WHERE pt.id IS NULL
UNION ALL SELECT 'news_without_tags', COUNT(*) FROM news n LEFT JOIN newsTags nt ON n.id = nt.newsId WHERE nt.id IS NULL
UNION ALL SELECT 'articles_without_tags', COUNT(*) FROM articles a LEFT JOIN articleTags at2 ON a.id = at2.articleId WHERE at2.id IS NULL;

